// Shared helpers over build/rules.json (generated by bin/build-rules.mjs). Zero dependencies.
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
export const readJSON = (p) => JSON.parse(readFileSync(p, 'utf8'))
export const kitVersion = () => readFileSync(join(ROOT, 'VERSION'), 'utf8').trim()

let cache
export function loadRules() { return (cache ??= readJSON(join(ROOT, 'build/rules.json'))) }
export function loadStacks() { return readJSON(join(ROOT, 'plugin/stacks.json')) }

// Rule-ID references in free text, expanding  X-23–26 · X-1…7 · X-1..10 · X-0/6/7 · X-0,6,7.
// `prefixes` (Set) filters out look-alikes such as UTF-8, SHA-256, P-256, CVE-2025.
const REF = /\b([A-Z]{1,8})-(\d+)((?:(?:–|…|\.\.\.?|-)\d+(?!\d|\.\d))|(?:[/,]\d+(?!\d|\.\d))+)?/g
export function extractRefs(text, prefixes) {
  const out = new Set()
  for (const m of text.matchAll(REF)) {
    const [, p, a, tail] = m
    if (prefixes && !prefixes.has(p)) continue
    const n = +a
    out.add(`${p}-${n}`)
    if (!tail) continue
    if (/^[/,]/.test(tail)) { for (const x of tail.split(/[/,]/).filter(Boolean)) out.add(`${p}-${+x}`); continue }
    const b = +tail.replace(/\D+/g, '')
    if (b > n && b - n <= 60) for (let i = n + 1; i <= b; i++) out.add(`${p}-${i}`)
  }
  return [...out]
}

export function expandStacks(stacks, map = loadStacks()) {
  const out = new Set()
  const add = (s) => { if (out.has(s)) return; out.add(s); for (const t of map.implies?.[s] || []) add(t) }
  for (const s of stacks || []) add(String(s).toLowerCase().trim())
  return out
}

// Rules for a set of stacks. include_core=false drops rules tagged only 'all'.
export function rulesFor({ stacks = [], topic, level, include_core = true } = {}) {
  const want = expandStacks(stacks)
  const words = (topic || '').toLowerCase().split(/[\s,]+/).filter((w) => w.length > 1)
  return loadRules().rules.filter((r) => {
    const specific = r.stacks.some((s) => s !== 'all' && want.has(s))
    if (!specific && !(include_core && r.stacks.includes('all'))) return false
    if (level && r.level !== level.toUpperCase()) return false
    if (!words.length) return true
    const hay = `${r.id} ${r.section} ${r.subsection} ${r.text}`.toLowerCase()
    return words.some((w) => hay.includes(w))
  })
}

export const ruleById = (id) => loadRules().rules.find((r) => r.id === String(id).toUpperCase().trim())

// "SEC-1 SEC-2 SEC-3 SEC-5" → "SEC-1–3,5"
export function compressIds(ids) {
  const by = new Map()
  for (const id of ids) { const [p, n] = id.split('-'); (by.get(p) || by.set(p, []).get(p)).push(+n) }
  return [...by].map(([p, ns]) => {
    ns.sort((a, b) => a - b); const parts = []
    for (let i = 0; i < ns.length;) { let j = i; while (ns[j + 1] === ns[j] + 1) j++; parts.push(j > i ? `${ns[i]}–${ns[j]}` : `${ns[i]}`); i = j + 1 }
    return `${p}-${parts.join(',')}`
  }).join(' ')
}

export function cmpSemver(a, b) {
  const pa = String(a).split('.').map(Number), pb = String(b).split('.').map(Number)
  for (let i = 0; i < 3; i++) if ((pa[i] || 0) !== (pb[i] || 0)) return (pa[i] || 0) - (pb[i] || 0)
  return 0
}
